 IEnumerator Start(){Application.logMessageReceived+=Err;Directory.CreateDirectory("Logs/FunctionalVisual");yield return null;yield return null;a=AccessController.Instance;g=a.GetComponent<DespachoGame>();m=a.GetComponent<DeskMenus>();
 Check(DeskMenus.Version=="v0.9.9-prototipo","actual version v099");Check(!P.narration&&!P.readingView&&P.textScale==1&&!D.highContrast,"fresh isolated defaults");a.ShowSettings();yield return new WaitForSecondsRealtime(3);yield return Tick();
 var inventory=new Inventory();foreach(string cat in new[]{"Inicio","Visual","Motor","Cognitiva","Audio","Controles","Glosario","Restaurar"}){a.OpenCategory(cat);yield return Tick();foreach(var e in Entries().Where(e=>!e.text.StartsWith("Volver a ")))inventory.rows.Add(new Row{category=cat,name=e.text,description=e.description??"",value=e.value??"",action=e.action!=null,enabled=e.enabled});}File.WriteAllText("Logs/Functional-controls.json",JsonUtility.ToJson(inventory,true));
 D.tutorial=true;D.autosave=false;m.Resume();g.StartFromMenu();Call("ShowOffice");yield return Tick();yield return new WaitForSecondsRealtime(.3f);
 var tutor=TutorialManager.Instance;Check(tutor.IsActive,"tutorial active in real campaign");var frame=(Image[])typeof(TutorialManager).GetField("frame",F).GetValue(tutor);float alpha=frame[0].color.a;yield return new WaitForSecondsRealtime(.19f);Check(Mathf.Abs(alpha-frame[0].color.a)>.001f,"tutorial frame pulse changes alpha normally");
 string tutorialPalette=Palette(tutor.transform);var body=(Text)typeof(TutorialManager).GetField("body",F).GetValue(tutor);Color bodyColor=body.color;int bodyFont=body.fontSize;
 P.reduceFlashes=true;yield return Tick();Check(frame.All(x=>x.color.a==1),"reduce flashes makes real tutorial frame static");yield return new WaitForSecondsRealtime(.2f);Check(frame.All(x=>x.color.a==1),"tutorial pulse remains static");P.reduceFlashes=false;yield return Tick();Check(frame[0].color.a<1,"tutorial pulse restored");
 D.highContrast=true;P.textScale=1.75f;yield return Tick();Check(body.color==bodyColor&&body.fontSize==bodyFont,"LIMIT illustrated tutorial text color and size unchanged by contrast/text scale");D.highContrast=false;P.textScale=1;D.tutorial=false;yield return Tick();
 // Exact real-game colors and fonts, after rerendering each screen.
 var country=((List<Country>)Get("countries")).First();
 foreach(string screen in new[]{"office","map","visit"}){
  D.highContrast=false;P.textScale=1;a.ClosePanels();if(screen=="office")Call("ShowOffice");else if(screen=="map")Call("ShowMap");else Call("StartVisit",country);yield return Tick();
  if(screen=="office"){P.simpleDocuments=true;var d=g.GetComponentInChildren<DeskDocument>();d.AccessSelect();d.AccessPlace();yield return new WaitForSecondsRealtime(.4f);}
  string colors=Palette(GameUI),fonts=Fonts(GameUI);Shot(screen+"-normal");
  D.highContrast=true;P.textScale=1.75f;if(screen=="office")Call("ShowOffice");else if(screen=="map")Call("ShowMap");else Call("ShowVisit");yield return Tick();
  if(screen=="office"){var d=g.GetComponentInChildren<DeskDocument>();if(!d.CanDecide){d.AccessSelect();d.AccessPlace();yield return new WaitForSecondsRealtime(.4f);}}
  Check(Palette(GameUI)==colors,"LIMIT "+screen+" illustrated graphics colors unchanged by high contrast");Check(Fonts(GameUI)==fonts,"LIMIT "+screen+" illustrated text sizes unchanged at 175 percent");Shot(screen+"-contrast-text175");
 }
 Call("ShowOffice");yield return Tick();D.highContrast=false;P.textScale=1;m.ShowPause();yield return Tick();string normal="";
 // Menus use their own canvas; compare actually rendered graphics after reconstruction.
 string MenuPalette()=>string.Join("|",m.GetComponentsInChildren<Graphic>().Where(x=>x.GetComponentInParent<Canvas>().sortingOrder==400).Select(x=>x.color.ToString("F3")));
 normal=MenuPalette();D.highContrast=true;m.ShowPause();yield return Tick();Check(normal!=MenuPalette(),"pause menu contrast changes actual graphic colors");Shot("pause-contrast");m.Resume();Call("ShowOffice");yield return Tick();
 // Labels read real values, not the preview fixture.
 typeof(DespachoGame).GetField("estabilidad",F).SetValue(g,23);typeof(DespachoGame).GetField("seguridad",F).SetValue(g,59);typeof(DespachoGame).GetField("prosperidad",F).SetValue(g,82);Call("ShowOffice");yield return Tick();P.symbols=false;P.narration=false;P.independentColor=true;a.SetReadingView(true);yield return Tick();string snap=string.Join("|",a.Snapshot().Select(e=>e.text));Check(snap.Contains("Estabilidad 23 / 100: en riesgo")&&snap.Contains("Seguridad 59 / 100: atención")&&snap.Contains("Prosperidad 82 / 100: estable"),"reader labels match real country values and thresholds");Shot("reader-live-indicators");P.independentColor=false;yield return Tick();Check(!a.Snapshot().Any(e=>e.text.StartsWith("[=] Estabilidad")),"expanded labels reverse when all suppliers off");P.symbols=true;yield return Tick();Check(a.Snapshot().Any(e=>e.text.StartsWith("[=] Estabilidad")),"symbols independently supplies labels");a.SetReadingView(false);
 string campaign=State();a.OpenCategory("Motor");yield return Tick();P.simpleDocuments=true;a.DemoDocument();a.DemoPlace();yield return Tick();Check(a.DemoOpened&&State()==campaign,"preview document opens without changing campaign");P.visualSounds=true;a.OpenCategory("Audio");yield return Tick();Entries().First(e=>e.text=="Ejemplo de aviso").action();yield return Tick();Check(State()==campaign,"preview notification leaves campaign unchanged");
 a.OpenCategory("Visual");P.independentColor=true;yield return Tick();Check(Entries().Any(e=>e.text.Contains("65 · estable"))&&State()==campaign,"preview explicitly uses fixture 65/48/30, not actual 23/59/82");
 // All text sizes fit and change fonts; interface changes geometry, not fonts.
 foreach(float size in new[]{.75f,1f,1.25f,1.5f,1.75f}){P.textScale=size;yield return Tick();Check(UI.GetComponentsInChildren<Text>().First(t=>t.text=="Alto contraste").fontSize==Mathf.RoundToInt(24*size),"actual accessible font size "+size);Check(UI.GetComponentsInChildren<Text>().All(t=>t.preferredHeight<=t.rectTransform.rect.height+3),"accessible text fits at "+size);}
 Shot("accessibility-175-contrast");P.textScale=1;P.interfaceScale=.8f;yield return Tick();var row=UI.GetComponentsInChildren<RectTransform>().First(x=>x.name=="Setting: Alto contraste");float small=row.rect.height,icon=row.Find("Icon").GetComponent<RectTransform>().rect.width;int font=row.GetComponentInChildren<Text>().fontSize;P.interfaceScale=1.2f;yield return Tick();row=UI.GetComponentsInChildren<RectTransform>().First(x=>x.name=="Setting: Alto contraste");Check(row.rect.height>small&&row.Find("Icon").GetComponent<RectTransform>().rect.width>icon&&row.GetComponentInChildren<Text>().fontSize==font,"interface scale changes card/icon geometry without font change");Check(State()==campaign,"all preview and layout changes preserve complete campaign snapshot");
 // Exercise the animation component used by the map prompt, with known timing.
 a.ClosePanels();m.Resume();var fixture=new GameObject("AuditWiggle",typeof(RectTransform));var wig=fixture.AddComponent<Wiggle>();var rt=(RectTransform)fixture.transform;var timer=typeof(Wiggle).GetField("timer",F);D.reduceMotion=false;P.reduceFlashes=false;timer.SetValue(wig,2.1f);yield return null;Check(rt.localScale!=Vector3.one||rt.localRotation!=Quaternion.identity,"Wiggle fixture moves without reduction");P.reduceFlashes=true;yield return null;Check(rt.localScale==Vector3.one&&rt.localRotation==Quaternion.identity,"reduce flashes suppresses real Wiggle component");P.reduceFlashes=false;timer.SetValue(wig,2.1f);yield return null;Check(rt.localScale!=Vector3.one||rt.localRotation!=Quaternion.identity,"Wiggle reduction reversible");Destroy(fixture);

 foreach(var spec in new[]{"Visual|Alto contraste|highContrast|D","Visual|Indicadores con etiquetas|independentColor|P","Visual|Reducir destellos|reduceFlashes|P","Motor|Seleccionar documentos con clics|simpleDocuments|P","Motor|Navegación por teclado|keyboard|P","Motor|Botones y zonas más grandes|largeTargets|P","Motor|Reducir animaciones|reduceMotion|D","Cognitiva|Instrucciones sencillas|simpleLanguage|P","Cognitiva|Ayudas de navegación|navigationHelp|P","Cognitiva|Símbolos explicativos|symbols|P","Cognitiva|Glosario disponible|glossary|P","Audio|Narración del sistema|narration|P","Audio|Audio mono|mono|P","Audio|Reducir sonidos agudos|softAudio|P","Audio|Avisos visuales|visualSounds|P"}){
  var parts=spec.Split('|');a.OpenCategory(parts[0]);yield return Tick();object store=parts[3]=="D"?(object)D:P;var field=store.GetType().GetField(parts[2]);bool before=(bool)field.GetValue(store);var e=Entries().First(x=>x.text==parts[1]);Check(e.enabled,"toggle available "+parts[1]);e.action();yield return Tick();Check((bool)field.GetValue(store)!=before,"toggle activates actual property "+parts[1]);Entries().First(x=>x.text==parts[1]).action();yield return Tick();Check((bool)field.GetValue(store)==before,"toggle reverses "+parts[1]);if(!before){Entries().First(x=>x.text==parts[1]).action();yield return Tick();}
 }
 foreach(var name in new[]{"Volumen maestro","Efectos de sonido","Interfaz","Volumen de narración"}){a.OpenCategory("Audio");yield return Tick();float old=Entries().First(x=>x.text==name).sliderValue;Entries().First(x=>x.text==name).sliderChange(.23f);yield return Tick();Check(Mathf.Abs(Entries().First(x=>x.text==name).sliderValue-.23f)<.001f,"slider actual value "+name);Entries().First(x=>x.text==name).sliderChange(old);yield return Tick();Check(Mathf.Abs(Entries().First(x=>x.text==name).sliderValue-old)<.001f,"slider reverses "+name);}
 foreach(var item in new[]{"Visual|Tamaño de texto|textScale|5","Visual|Escala de interfaz|interfaceScale|5","Audio|Velocidad de voz|speechRate|3"}){var parts=item.Split('|');var field=typeof(AccessPreferences).GetField(parts[2]);object before=field.GetValue(P);a.OpenCategory(parts[0]);yield return Tick();for(int n=0;n<int.Parse(parts[3]);n++){Entries().First(x=>x.text==parts[1]).action();yield return Tick();}Check(field.GetValue(P).Equals(before),"all cyclic values return to original "+parts[1]);}
 P.Save();D.Save();File.WriteAllText("Logs/Functional-evidence-expected.json",JsonUtility.ToJson(P));File.WriteAllText("Logs/Functional-evidence-expected-general.json",JsonUtility.ToJson(D));File.WriteAllText("Logs/Functional-evidence-directory.txt",DeskPreferences.TestDirectory);log.Add("COMPLETE "+log.Count(x=>x.StartsWith("PASS "))+" PASS; measured rendered properties and campaign state, screenshots are automated game captures");File.WriteAllLines("Logs/Functional-evidence.txt",log);EditorApplication.Exit(0);
 }
}
public static class FunctionalEvidenceRunner {
 public static void Restart(){DeskPreferences.TestDirectory=File.ReadAllText("Logs/Functional-evidence-directory.txt");DeskPreferences.Load();AccessPreferences.Load();bool ok=JsonUtility.ToJson(AccessPreferences.Current)==File.ReadAllText("Logs/Functional-evidence-expected.json")&&JsonUtility.ToJson(DeskPreferences.Current)==File.ReadAllText("Logs/Functional-evidence-expected-general.json");File.WriteAllText("Logs/Functional-evidence-restart.txt",ok?"PASS separate process preserves all toggles active and exact custom preferences":"FAIL complete restart");EditorApplication.Exit(ok?0:1);}
 public static void Run(){SessionState.SetBool("FunctionalAudit",true);SessionState.SetString("FunctionalAuditDir",Path.Combine(Path.GetTempPath(),"DespachoFunctional-"+Guid.NewGuid().ToString("N")));EditorApplication.EnterPlaymode();}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Before(){if(!SessionState.GetBool("FunctionalAudit",false))return;DeskSaveStore.TestDirectory=SessionState.GetString("FunctionalAuditDir","");DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory;}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void After(){if(!SessionState.GetBool("FunctionalAudit",false))return;SessionState.SetBool("FunctionalAudit",false);new GameObject("FunctionalAudit").AddComponent<FunctionalEvidenceProbe>();}
}
